            b"HTTP/1.1 200 Test\r\nTransfer-Encoding: gzip\r\n\r\n",
            "unsupported",
        ),
        (
            (
                b"HTTP/1.1 200 Test\r\nTransfer-Encoding: chunked\r\n\r\n"
